使用嵌套的for循环打印九九乘法表，代码如下。
     static void Main(string[] args)
     {
         int iRow, iColumn;                                     
//定义行数和列数
         for (iRow = 1; iRow < 10; iRow++)                      
//行数循环
         {
             for (iColumn = 1; iColumn <= iRow; iColumn++)      
//列数循环
             {
                 Console.Write("{0}*{1}={2} ", iColumn, iRow, 
iRow * iColumn);   //输出每一行的数据
             }
             Console.WriteLine();                               
//换行
         }
         Console.ReadLine();
     }
